        case 2: v = QVariant(QStringLiteral("abc")); break; // non-integer -> expect true
        default: v = QVariant(QByteArray("\x01\x02", 2));  // non-integer convertible -> expect true
    }
    bool r = NeovimQt::variant_not_zero(v);

    if (scenario == 0) {
