    // Build a small QVariantList of QByteArray elements to exercise the success path.
    QVariantList blist;
    unsigned int blen = (*FUZZ_PARAM(unsigned int)) % 6; // keep small
    std::string seed_b = FUZZ_PARAM_STR();
    QByteArray base_b(seed_b.data(), (int)seed_b.size());
    for (unsigned int i = 0; i < blen; ++i) {
