import random
import string
from typing import List

# Data type: UTF-8 text
# Goal: Produce interesting, valid UTF-8 sequences that exercise QString::fromUtf8,
# NeovimQt encoding/decoding, and various API paths that accept QByteArray/QString.
# We include mixtures of:
# - ASCII commands/identifiers
# - Multi-byte Unicode (BMP and supplementary planes)
# - Combining marks and zero-width joiners
# - RTL/LTR markers
# - Emoji sequences (including ZWJ family)
# - Different line endings and whitespace
# - Long/short lengths within a bound
# - Valid path-like strings
# The result must be <= 4096 bytes.

CONTROL_SEQUENCES = [
    "<Esc>", "<CR>", "<Tab>", "<BS>", "<C-a>", "<C-b>", "<C-c>",
]

RUNTIME_CMDS = [
    ":set number", ":set nonumber", ":setlocal tabstop=4", ":pwd", ":ls", ":echo has('nvim')",
    ":echo strwidth('å')", ":echo expand('%:p')",
]

# Some interesting Unicode code points and ranges
COMBINING = [
    0x0301, 0x0308, 0x0300, 0x20DD, 0x20DE, 0x20EF  # combining accents/enclosing marks
]
ZERO_WIDTH = [0x200B, 0x200C, 0x200D]  # ZWSP, ZWNJ, ZWJ
RTL_MARKS = [0x202E, 0x202A, 0x202B, 0x2067, 0x2066]  # bidi controls
EMOJI = [
    0x1F600, 0x1F603, 0x1F604, 0x1F602, 0x1F923,  # smileys
    0x1F44D, 0x1F44E, 0x1F44F,                     # gestures
    0x1F468, 0x1F469, 0x1F9D1,                     # person(s) base
    0x1F680, 0x1F4A9, 0x1F3F3, 0xFE0F, 0x200D      # variation selector & ZWJ
]

ASCII_WORDS = [
    "buffer", "window", "tabpage", "option", "variable", "highlight", "namespace",
    "get", "set", "clear", "attach", "detach", "subscribe", "unsubscribe",
]

PATH_PARTS = ["/tmp", "/home/user", "C:/Users/Test", "./relative", "../up", "~", "/var/log"]

def _rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))

def _rand_choice(r: random.Random, seq: List[str]):
    return seq[r.randrange(len(seq))]

def _rand_codepoint(r: random.Random) -> int:
    # Choose from diverse sets with some probability weights
    roll = r.random()
    if roll < 0.25:
        return r.randrange(0x20, 0x7F)  # printable ASCII
    if roll < 0.45:
        return r.choice(COMBINING)
    if roll < 0.6:
        return r.choice(ZERO_WIDTH)
    if roll < 0.72:
        return r.choice(RTL_MARKS)
    if roll < 0.92:
        # BMP letters, symbols
        return r.randrange(0x00A0, 0x07FF)
    else:
        return r.choice(EMOJI)

def _encode_utf8(codepoints: List[int]) -> bytes:
    return "".join(chr(cp) for cp in codepoints).encode("utf-8")

def _rand_identifier(r: random.Random, min_len=3, max_len=16) -> str:
    chars = string.ascii_letters + string.digits + "_"
    n = r.randint(min_len, max_len)
    s = r.choice(string.ascii_letters + "_") + "".join(r.choice(chars) for _ in range(n-1))
    return s

def _rand_path(r: random.Random) -> str:
    parts = [r.choice(PATH_PARTS)]
    for _ in range(r.randint(0, 3)):
        parts.append(_rand_identifier(r, 3, 10))
    return "/".join(p.strip("/") for p in parts)

def _zwj_emoji_sequence(r: random.Random) -> List[int]:
    # Build a simple ZWJ emoji family-like sequence if possible
    base = r.choice([0x1F468, 0x1F469, 0x1F9D1])  # person
    activity = r.choice([0x1F3C3, 0x1F9D9, 0x1F57A, 0x1F469, 0x1F468])
    return [base, 0x200D, activity, 0xFE0F]

def _unicode_mix(r: random.Random, target_len: int) -> bytes:
    cps: List[int] = []
    while len(_encode_utf8(cps)) < target_len:
        choice = r.random()
        if choice < 0.1:
            cps.extend(_zwj_emoji_sequence(r))
        else:
            cps.append(_rand_codepoint(r))
        # Occasionally insert newline or CRLF
        if r.random() < 0.05:
            cps.append(ord('\n'))
        elif r.random() < 0.03:
            cps.extend([ord('\r'), ord('\n')])
        # Limit growth
        if len(cps) > target_len * 2:
            break
    data = _encode_utf8(cps)
    # Trim precisely to target_len without splitting UTF-8: back off to last valid boundary (already valid string)
    if len(data) > target_len:
        data = data[:target_len]
        # ensure valid UTF-8 by decoding fallback: step back until valid
        while True:
            try:
                data.decode('utf-8')
                break
            except UnicodeDecodeError:
                data = data[:-1]
    return data

def _assemble_sections(r: random.Random) -> bytes:
    sections: List[bytes] = []

    # Header: plausible ex command or identifier
    if _rand_bool(r):
        sections.append(_rand_choice(r, RUNTIME_CMDS).encode('utf-8'))
    else:
        ident = _rand_identifier(r)
        sections.append(ident.encode('utf-8'))

    # Separator
    sections.append(b"\n")

    # A path-like chunk (for vim_get_name etc.)
    if _rand_bool(r):
        sections.append(_rand_path(r).encode('utf-8'))
        sections.append(b"\n")

    # Control key notation and mode flags
    if _rand_bool(r):
        seq = _rand_choice(r, CONTROL_SEQUENCES)
        mode = r.choice(["n", "i", "t", "v", "!", "x"])
        sections.append(f"{seq} {mode}".encode('utf-8'))
        sections.append(b"\n")

    # Mixed Unicode payload of random length chunk
    mix_len = r.randint(32, 256)
    sections.append(_unicode_mix(r, mix_len))
    sections.append(b"\n")

    # Add some combining sequences anchored to base letters
    base = r.choice(["A", "e", "o", "n", "उ", "Ω"])  # ASCII and non-ASCII bases
    comb = ''.join(chr(r.choice(COMBINING)) for _ in range(r.randint(1, 4)))
    sections.append((base + comb).encode('utf-8'))
    sections.append(b"\n")

    # Include bidi controls around a word to exercise rendering
    rtl_word = "שלום"  # Hebrew
    ltr_word = "hello"
    bidi = chr(r.choice(RTL_MARKS)) + rtl_word + chr(0x202C) + " " + ltr_word
    sections.append(bidi.encode('utf-8'))
    sections.append(b"\n")

    # Optional emoji ZWJ sequence
    if _rand_bool(r):
        sections.append(_encode_utf8(_zwj_emoji_sequence(r)))
        sections.append(b"\n")

    # Option name/value pair style (for get/set option APIs)
    opt = r.choice(["number", "relativenumber", "tabstop", "expandtab", "background", "encoding"]) \
          + "=" + r.choice(["0", "1", "2", "4", "8", "dark", "light", "utf-8"]) 
    sections.append(opt.encode('utf-8'))

    # Ensure size limit
    data = b"".join(sections)
    if len(data) > 4096:
        data = data[:4096]
        # back off to valid utf-8 boundary
        while True:
            try:
                data.decode('utf-8')
                break
            except UnicodeDecodeError:
                data = data[:-1]
    return data


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomly choose a profile for the buffer composition
    profile = r.random()
    if profile < 0.3:
        # Short command-centric buffer
        parts = [
            _rand_choice(r, RUNTIME_CMDS).encode('utf-8'),
            b"\n",
            _unicode_mix(r, r.randint(16, 64)),
        ]
        data = b"".join(parts)
    elif profile < 0.6:
        # Path heavy with identifiers and options
        parts = [
            _rand_path(r).encode('utf-8'), b"\n",
            _rand_identifier(r).encode('utf-8'), b" ", _rand_identifier(r).encode('utf-8'), b"\n",
            _unicode_mix(r, r.randint(64, 160)), b"\n",
            ("set " + _rand_choice(r, ["number", "nonumber", "rnu", "nornu"]) ).encode('utf-8')
        ]
        data = b"".join(parts)
    else:
        # Rich mixed sections
        data = _assemble_sections(r)

    # Final guard: ensure valid UTF-8
    try:
        data.decode('utf-8')
    except UnicodeDecodeError:
        # Trim until valid
        while data:
            try:
                data = data[:-1]
                data.decode('utf-8')
                break
            except UnicodeDecodeError:
                continue
        if not data:
            data = b""
    return data

import json
import random
import struct
from typing import Any, Dict, List, Tuple

# We generate a UTF-8 JSON object (dictionary) suitable for QVariantMap-like consumption
# by fuzz stubs expecting a map/dictionary. We keep values heterogeneous but valid
# JSON types (strings, numbers, booleans, null, arrays, nested objects). No mutation
# beyond seeded randomness, and total size <= 4096 bytes.

PRIMITIVE_KEYS = [
    "name", "title", "description", "event", "mode", "type",
    "path", "dir", "file", "hl_group", "option", "var",
]

# Common option-like keys useful across Neovim APIs
NVIM_OPTION_KEYS = [
    "rgb", "ext_linegrid", "popupmenu", "tabline", "winblend",
    "pumblend", "cursorline", "number", "relativenumber", "signcolumn",
]

# Some numeric-ish keys
NUMERIC_KEYS = [
    "width", "height", "row", "col", "start", "end", "lnum",
    "src_id", "ns_id", "grid", "tabpage", "window", "buffer",
]

# Helper to make a short unicode string
UNICODE_SAMPLES = [
    "こんにちは", "привет", "γειά", "مرحبا", "שָׁלוֹם", "नमस्ते",
    "こんにちは世界", "neovim", "Δοκιμή", "テスト", "🚀✨", "café",
]

REG_TYPES = ["v", "V", "l", "c", "b"]


def seeded_rand(seed: int) -> random.Random:
    rnd = random.Random()
    rnd.seed(seed)
    return rnd


def rand_unicode(rnd: random.Random) -> str:
    if rnd.random() < 0.7:
        return rnd.choice(UNICODE_SAMPLES)
    # fallback random printable mix
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-:/.,<>~!@#$%^&*()[]{}" \
               + " "
    n = rnd.randint(3, 20)
    return "".join(rnd.choice(alphabet) for _ in range(n))


def rand_bool(rnd: random.Random) -> bool:
    return bool(rnd.getrandbits(1))


def rand_number(rnd: random.Random) -> int:
    # keep within modest bounds
    choices = [
        rnd.randint(0, 2000),
        rnd.randint(-1000, 1000),
        0, 1, 2, 80, 120, 999,
    ]
    return rnd.choice(choices)


def rand_float(rnd: random.Random) -> float:
    return rnd.choice([0.0, 1.0, 0.5, rnd.random() * 10.0])


def rand_register_type(rnd: random.Random) -> str:
    return rnd.choice(REG_TYPES)


def rand_lines(rnd: random.Random) -> List[str]:
    count = rnd.randint(1, 5)
    return [rand_unicode(rnd) for _ in range(count)]


def rand_color_name(rnd: random.Random) -> str:
    colors = [
        "Red", "Green", "Blue", "Yellow", "Magenta", "Cyan",
        "Black", "White", "Gray", "Orange", "Purple", "Brown",
    ]
    return rnd.choice(colors)


def rand_hl_group(rnd: random.Random) -> str:
    groups = [
        "ErrorMsg", "WarningMsg", "Visual", "Search", "DiffAdd", "DiffDelete",
        "Identifier", "Statement", "PreProc", "Type", "Underlined", "Todo",
    ]
    return rnd.choice(groups)


def make_virtual_text_chunks(rnd: random.Random) -> List[List[Any]]:
    # Structure like [[text, hl_group, {opts...}], ...]
    chunks: List[List[Any]] = []
    for _ in range(rnd.randint(1, 3)):
        text = rand_unicode(rnd)
        group = rand_hl_group(rnd)
        opts = {}
        if rnd.random() < 0.5:
            opts["hl_mode"] = rnd.choice(["combine", "replace", "blend"])
        if rnd.random() < 0.4:
            opts["virt_text_pos"] = rnd.choice(["eol", "overlay", "right_align"])
        chunks.append([text, group, opts])
    return chunks


def make_namespace_map(rnd: random.Random) -> Dict[str, int]:
    # Map of namespace names to ids
    d: Dict[str, int] = {}
    for _ in range(rnd.randint(1, 4)):
        d[f"ns_{rand_unicode(rnd)[:6].strip()}"] = rnd.randint(1, 1000)
    return d


def make_buffer_opts(rnd: random.Random) -> Dict[str, Any]:
    # Options akin to nvim_buf_attach/nvim_ui_attach
    m: Dict[str, Any] = {}
    m["rgb"] = rand_bool(rnd)
    m["ext_linegrid"] = rand_bool(rnd)
    if rnd.random() < 0.5:
        m["ext_hlstate"] = rand_bool(rnd)
    if rnd.random() < 0.3:
        m["ext_cmdline"] = rand_bool(rnd)
    return m


def rand_value(rnd: random.Random, depth: int = 0) -> Any:
    # Generate JSON-serializable heterogeneous values
    if depth > 2:
        return rnd.choice([rand_unicode(rnd), rand_number(rnd), rand_bool(rnd), None])

    choice = rnd.random()
    if choice < 0.30:
        return rand_unicode(rnd)
    elif choice < 0.55:
        return rand_number(rnd)
    elif choice < 0.65:
        return rand_float(rnd)
    elif choice < 0.80:
        return rand_bool(rnd)
    elif choice < 0.90:
        # array
        return [rand_value(rnd, depth + 1) for _ in range(rnd.randint(1, 4))]
    else:
        # nested object
        sz = rnd.randint(1, 4)
        o: Dict[str, Any] = {}
        for _ in range(sz):
            key = rand_unicode(rnd)
            o[key] = rand_value(rnd, depth + 1)
        return o


def build_dictionary(rnd: random.Random) -> Dict[str, Any]:
    d: Dict[str, Any] = {}

    # Fill with some recognizable, valid keys seen in the API
    d["width"] = rnd.choice([80, 100, 120, rand_number(rnd)])
    d["height"] = rnd.choice([24, 30, 40, rand_number(rnd)])
    d["enable_rgb"] = rand_bool(rnd)
    d["event"] = rnd.choice(["redraw", "notification", "custom_event", rand_unicode(rnd)])
    d["name"] = rand_unicode(rnd)
    d["mode"] = rnd.choice(["n", "i", "v", "c", "t"])  # common nvim modes
    d["hl_group"] = rand_hl_group(rnd)
    d["color_name"] = rand_color_name(rnd)

    # Namespace and buffer/window/tab identifiers (integers)
    d["ns_id"] = rnd.randint(0, 10)
    d["buffer"] = rnd.randint(1, 5)
    d["window"] = rnd.randint(1, 5)
    d["tabpage"] = rnd.randint(1, 5)

    # Options maps
    d["ui_options"] = make_buffer_opts(rnd)
    d["buf_attach_opts"] = make_buffer_opts(rnd)

    # Virtual text chunks (commonly used structure)
    d["virtual_text_chunks"] = make_virtual_text_chunks(rnd)

    # Register-like type
    d["register_type"] = rand_register_type(rnd)

    # Lines array
    d["lines"] = rand_lines(rnd)

    # Namespaces map
    d["namespaces"] = make_namespace_map(rnd)

    # Additional random key-values
    extra_count = rnd.randint(3, 8)
    for _ in range(extra_count):
        key_choice = rnd.random()
        if key_choice < 0.3:
            key = rnd.choice(PRIMITIVE_KEYS)
        elif key_choice < 0.6:
            key = rnd.choice(NVIM_OPTION_KEYS)
        elif key_choice < 0.85:
            key = rnd.choice(NUMERIC_KEYS)
        else:
            key = f"x_{rand_unicode(rnd)[:8].strip()}"
        # Ensure keys are unique by appending suffixes if needed
        base_key = key
        suffix = 1
        while key in d:
            key = f"{base_key}_{suffix}"
            suffix += 1
        d[key] = rand_value(rnd)

    return d


def generate(seed: int) -> bytes:
    rnd = seeded_rand(seed)

    # Build a dictionary and serialize as JSON UTF-8 bytes
    # Keep size under 4096 bytes by adjusting content if needed
    doc = build_dictionary(rnd)

    # A small chance to produce a top-level list of maps, still valid QVariant conversion
    if rnd.random() < 0.2:
        top: Any = [build_dictionary(rnd) for _ in range(rnd.randint(1, 3))]
    else:
        top = doc

    # Compact JSON
    s = json.dumps(top, ensure_ascii=False, separators=(",", ":"))

    b = s.encode("utf-8")
    if len(b) <= 4096:
        return b

    # If too large, iteratively trim by removing some keys
    if isinstance(top, dict):
        keys = list(top.keys())
        rnd.shuffle(keys)
        while len(b) > 4096 and keys:
            k = keys.pop()
            top.pop(k, None)
            s = json.dumps(top, ensure_ascii=False, separators=(",", ":"))
            b = s.encode("utf-8")
    elif isinstance(top, list):
        while len(b) > 4096 and top:
            top.pop()
            s = json.dumps(top, ensure_ascii=False, separators=(",", ":"))
            b = s.encode("utf-8")

    # Final guard: if still too big, truncate bytes at a boundary (JSON may become invalid,
    # so instead fall back to a minimal valid object).
    if len(b) > 4096:
        b = json.dumps({"width": 80, "height": 24, "enable_rgb": True}).encode("utf-8")

    return b
